import {createOnlineSession,requestOnlineSeat} from './online-client.js';
import {roomCode,validRoomCode} from './online-protocol.js';
import {footballTeam} from './football-teams.js';
export function onlineInvite(code){const link=new URL(location.href);link.search='?place=pitch&night=1&experience=football&room='+code;link.hash='';return link.href;}
export async function copyOnlineInvite(session,toast){try{await navigator.clipboard.writeText(onlineInvite(session.code));toast?.('邀请链接已复制，发给朋友即可');return true;}catch{toast?.('请复制房间码：'+session.code);return false;}}
export function buildOnlineLobby({getOptions,onEnter,toast}){
 const $=id=>document.getElementById(id);let session=null,unsubscribe=null,busy=false;
 function render(){const room=session?.room;$('match-dialog').classList.toggle('online-room-open',!!session);$('match-dialog-title').textContent=session?'好友联机房间':'这一场，迎战谁？';$('match-intro-copy').textContent=session?'房间已创建，把邀请链接或房间码发给朋友。':'可以与朋友联机对战，也可以控制拜仁踢一场 3 分钟人机赛。';$('online-lobby-idle').hidden=!!session;$('online-lobby-room').hidden=!session;$('online-create').disabled=busy;$('online-join').disabled=busy;if(!session)return;$('online-code').textContent=session.code.slice(0,4)+' '+session.code.slice(4);$('online-side').textContent='你控制'+(session.team==='home'?'拜仁':footballTeam(session.opponent).name)+' · '+(session.team==='home'?'房主':'朋友');$('online-home-status').textContent=status('home',room);$('online-away-status').textContent=status('away',room);$('online-away-label').textContent=footballTeam(session.opponent).short;$('online-ready').disabled=session.connection!=='connected'||busy;$('online-ready').textContent='准备并进入球场 →';$('online-message').textContent=session.error||'双方进入球场并加载完成后，自动倒数开球。';}
 function status(team,room){const seat=room?.seats.find(s=>s.team===team);return !seat?.connected?'等待加入':seat.ready?'已准备':'已连接';}
 function saved(code){try{return JSON.parse(sessionStorage.getItem('arena-online-'+code)||'null');}catch{return null;}}
 async function connect(code){if(busy)return;busy=true;$('online-message').textContent=code?'正在加入房间…':'正在创建房间…';render();try{const existing=code?saved(roomCode(code)):null,seat=await requestOnlineSeat(code,code?{token:existing?.token}:{opponent:getOptions().opponent});session?.close();unsubscribe?.();session=createOnlineSession(seat);try{sessionStorage.setItem('arena-online-'+seat.code,JSON.stringify(seat));}catch{}unsubscribe=session.subscribe(render);render();await session.connect();}catch(e){session?.close();session=null;unsubscribe?.();$('online-message').textContent=e.message||'连接失败，请重试';}finally{busy=false;render();}}
 function open(){const panel=$('online-lobby');panel.hidden=false;const code=new URLSearchParams(location.search).get('room');if(code)$('online-room-input').value=roomCode(code);panel.scrollIntoView({block:'nearest',behavior:'smooth'});render();}
 $('match-online').onclick=open;$('online-create').onclick=()=>connect();$('online-join-form').onsubmit=e=>{e.preventDefault();const code=roomCode($('online-room-input').value);if(!validRoomCode(code)){$('online-message').textContent='请输入 8 位房间码';return;}connect(code);};$('online-copy').onclick=()=>session&&copyOnlineInvite(session,toast);$('online-leave').onclick=()=>{session?.leave();session=null;unsubscribe?.();$('online-message').textContent='已离开，可创建新的房间。';render();};$('online-ready').onclick=()=>{if(session?.connection==='connected')onEnter(session);};
 return{open,reset(){session=null;unsubscribe?.();const url=new URL(location.href);url.searchParams.delete('room');history.replaceState(null,'',url);render();},get session(){return session;}};
}
